data.mutation:
mutation CreateLocation($payloadW: [LocationUpsertPayloadInput!]!,$payloadWI: [LocationUpsertPayloadInput!]!,$payloadPS:[ProductionSetupUpsertPayloadInput!]!) {
  workcenterLocation:upsertLocation(payload:$payloadW) {
    id
},
   workcenterInputLocation:upsertLocation(payload:$payloadWI) {
    id
},
  upsertProductionSetup(payload: $payloadPS) {
    id
  workcenterId
  }
}

data.query:
query Query($where: WorkcenterWhereInput, $orderBy: [WorkcenterOrderByInput!], $first: Int, $after: String) {
  workcenter(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
    facilityId
      }
    }
  }
}

